export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <header className="absolute left-0 top-0 z-20 w-full px-4 py-4 text-[#f6efe4] sm:px-6">
      <div className="mx-auto flex max-w-[1440px] items-center justify-between gap-4">

        {/* Logo */}
        <a
          href="#"
          aria-label="Stampers home"
          className="inline-flex items-center"
        >
          <StampersLogo />
        </a>

        {/* Desktop Navigation */}
        <nav className="hidden items-center gap-8 text-sm uppercase tracking-[0.18em] md:flex">
          {navLinks.map((link) => (
            <a
              key={link}
              href="#"
              className="relative transition-opacity duration-300 hover:opacity-80
                         after:absolute after:left-0 after:bottom-[-2px]
                         after:h-[2px] after:w-0 after:bg-white
                         after:transition-all after:duration-300
                         hover:after:w-full"
            >
              {link}
            </a>
          ))}
        </nav>

        {/* Hamburger Button */}
        <button
          type="button"
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle navigation menu"
          aria-expanded={menuOpen}
          className="relative z-50 flex h-10 w-10 flex-col items-center justify-center gap-[6px] md:hidden"
        >
          <span
            className={`h-[2px] w-7 bg-white transition-all duration-300 ${
              menuOpen ? "translate-y-[8px] rotate-45" : ""
            }`}
          />

          <span
            className={`h-[2px] w-7 bg-white transition-all duration-300 ${
              menuOpen ? "opacity-0" : ""
            }`}
          />

          <span
            className={`h-[2px] w-7 bg-white transition-all duration-300 ${
              menuOpen ? "-translate-y-[8px] -rotate-45" : ""
            }`}
          />
        </button>
      </div>

      {/* Mobile Menu */}
      <div
        className={`md:hidden overflow-hidden transition-all duration-300 ease-in-out ${
          menuOpen
            ? "mt-4 max-h-96 opacity-100"
            : "max-h-0 opacity-0"
        }`}
      >
        <nav className="flex flex-col gap-5 border-t border-white/20 pt-5 pb-4 text-sm uppercase tracking-[0.18em]">
          {navLinks.map((link) => (
            <a
              key={link}
              href="#"
              onClick={() => setMenuOpen(false)}
              className="transition-opacity duration-300 hover:opacity-60"
            >
              {link}
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
}